/* ============ vibe coding: the first session runs once when the demo is seen ============ */
(function session() {
  const demo = $('#vb-demo'); if (!demo || RM) return;
  const you = $('#vb-you'), lines = $$('#vb-lines li'), url = $('#vb-url'), text = you.textContent;
  demo.classList.add('vb-anim'); url.textContent = 'starting preview…';
  const io = watch(demo, async v => {
    if (!v) return; io.disconnect();
    you.textContent = ''; const cur = document.createElement('span'); cur.className = 'cur';
    for (let i = 1; i <= text.length; i++) { you.textContent = text.slice(0, i); you.appendChild(cur); await wait(26); }
    cur.remove(); await wait(400);
    for (const l of lines) { l.classList.add('in'); await wait(560); }
    url.textContent = 'your-domain.com'; demo.classList.add('done');
  }, { threshold: 0.4 });
})();
/* ============ vibe coding: the two real sign-in paths ============ */
(function paths() {
  const btns = $$('.vb-seg button');
  btns.forEach(b => b.addEventListener('click', () => {
    const k = b.dataset.path;
    btns.forEach(x => x.setAttribute('aria-pressed', String(x === b)));
    $$('[data-path]').forEach(el => { if (el.tagName !== 'BUTTON') el.hidden = el.dataset.path !== k; });
  }));
})();

