export type NxmLoad = {
  slots?: Record<string, string>; data?: unknown; jsonLd?: object[]; crumb?: string;
  /** per-item particle colours (game pages) */ particles?: { from: string; to: string };
  /** full breadcrumb trail below Home, when the route's ancestors aren't in the registry */ trail?: { name: string; path: string }[];
};

/** The new site lives under /nxm on staging until launch (then ""). Links a
 *  loader renders to other NEW pages go through this. */
/** NXM_ROOT=1 (launch): the new site answers at the real URLs (middleware.ts
 *  rewrites them to app/nxm), so links drop the /nxm staging prefix. */
export const NXM_ROOT = process.env.NXM_ROOT === "1";
export const NXM_BASE = NXM_ROOT ? "" : "/nxm";
/** Strip the /nxm staging prefix from every link in rendered markup and page
 *  data once the site is live at the root. Asset paths under /nxm/ (public/nxm,
 *  they all end in a file extension) are left alone; anything this misses (a
 *  link a page script builds client-side) still lands via middleware's 301. */
export function unstage(html: string): string {
  if (!NXM_ROOT) return html;
  return html.replace(/(["'(=\s])\/nxm(\/[^"'\s)<>?#]*)?(?=["'\s)<>?#])/g, (m, pre: string, rest?: string) =>
    rest && /\.[a-z0-9]{2,5}$/i.test(rest) ? m : pre + (rest || "/"));
}
export const nxmHref = (route: string) => (NXM_BASE + (route === "/" ? "" : route)) || "/";

