import "server-only";
import { AU_ICONS } from "../_aurora/icons";
import { CAST, avatarSvg, type CastId } from "./ai-agents-cast";
import { esc, introSpan, productLd, usd, vpsPlans, type NxmLoad, type VpsPlan } from "./lib";

/**
 * /ai-agents: the AI agent hosting hub (native page, tools/nxm/native/ai-agents).
 *
 * System data, per request:
 *  - the three suggested sizes (starter, standard, pro): the real db.plan rows,
 *    with name, vCPU, RAM, NVMe, price and intro price as checkout has them;
 *  - every deploy link: the real deployHref() for that plan (vpsPlans).
 *  - JSON-LD Product/AggregateOffer from the same plans.
 * Missing plans throw (fail closed). The page makes no claims about agent
 * templates existing: the copy labels them "coming soon".
 *
 * The cast (ai-agents-cast.ts) is Nxeon's own original artwork.
 */

const SIZES = ["starter", "standard", "pro"] as const;
type Size = (typeof SIZES)[number];

/** Which cast members we suggest for each size (copy, not data). */
const FITS: Record<Size, { ids: CastId[]; good: string }> = {
  starter: { ids: ["visor", "bit", "quill", "plug"], good: "Chat bots on a hosted model, Claude Code jobs, small MCP servers" },
  standard: { ids: ["claw", "flow"], good: "OpenClaw with a few channels, n8n with Postgres" },
  pro: { ids: ["claw", "bit"], good: "Browser automation, several agents on one box" },
};

const ROCKET = `<span class="nxm-rk"><svg class="au-ic" viewBox="0 0 24 24" aria-hidden="true">${AU_ICONS.rocket}</svg></span>`;
const ARW = `<span class="nxm-arw" aria-hidden="true">→</span>`;
const d = (dollars: number) => usd(Math.round(dollars * 100));

/** The avatars' shared gradients, emitted once (avatars reference them by id). */
const DEFS = `<svg id="ag-defs" width="0" height="0" style="position:absolute" aria-hidden="true" focusable="false"><defs>
<linearGradient id="ag-claw" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#FF5BA8"/><stop offset=".55" stop-color="#E5197E"/><stop offset="1" stop-color="#A80E58"/></linearGradient>
<linearGradient id="ag-claw-2" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#FF8CC2"/><stop offset="1" stop-color="#E5197E"/></linearGradient>
<linearGradient id="ag-visor" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#2E3962"/><stop offset="1" stop-color="#121931"/></linearGradient>
<linearGradient id="ag-quill" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#F3A27C"/><stop offset=".55" stop-color="#DE7A55"/><stop offset="1" stop-color="#B6553A"/></linearGradient>
<linearGradient id="ag-plug" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#6B95FF"/><stop offset=".55" stop-color="#3B6BE8"/><stop offset="1" stop-color="#2648B8"/></linearGradient>
<linearGradient id="ag-flow" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#AD8CFF"/><stop offset=".55" stop-color="#7B3FEF"/><stop offset="1" stop-color="#5520C8"/></linearGradient>
<linearGradient id="ag-flow-2" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#D2C1FF"/><stop offset="1" stop-color="#8E5BFF"/></linearGradient>
<linearGradient id="ag-bit" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#8CEBF7"/><stop offset=".5" stop-color="#4E8DFF"/><stop offset="1" stop-color="#3561E0"/></linearGradient>
</defs></svg>`;

function castHtml() {
  return CAST.map((c, i) =>
    `<li class="ag-c" style="--acc:${c.acc};--i:${i}" tabindex="0" aria-label="${esc(`${c.name}: runs ${c.runs}. “${c.line}”`)}">` +
    `<span class="ag-c-say" aria-hidden="true">${esc(c.line)}</span>` +
    `<span class="ag-c-av">${avatarSvg(c.id)}</span>` +
    `<b class="ag-c-n">${esc(c.name)}</b><span class="ag-c-r">runs ${esc(c.runs)}</span></li>`,
  ).join("");
}

function planCard(p: VpsPlan, size: Size, pop: boolean) {
  const price = p.i != null
    ? `<p class="pp"><b>${d(p.i)}</b><s>${d(p.p)}</s><span>${introSpan(p.it)}</span></p><p class="then">Then ${d(p.p)} a month</p>`
    : `<p class="pp"><b>${d(p.p)}</b><span>/month</span></p><p class="then"></p>`;
  const cta = pop
    ? `<a class="nxm-btn au-hov" href="${esc(p.href)}">${ROCKET}<span class="nxm-bt">Deploy ${esc(p.n)}</span>${ARW}</a>`
    : `<a class="nxm-glassbtn" href="${esc(p.href)}"><span class="nxm-bt">Deploy ${esc(p.n)}</span></a>`;
  const fit = FITS[size];
  return `<article class="au-card ag-plan${pop ? " pop" : ""}">${pop ? `<span class="tag">Good starting size</span>` : ""}` +
    `<div class="ag-plan-av" aria-hidden="true">${fit.ids.map((id) => avatarSvg(id)).join("")}</div>` +
    `<small class="k">${esc(p.n)}</small>${price}` +
    `<ul><li>${p.cpu} vCPU · ${p.ram} GB RAM · ${p.disk} GB NVMe</li><li>${esc(fit.good)}</li><li>Full root · your own VM</li></ul>${cta}</article>`;
}

export async function load(_p: Record<string, string>): Promise<NxmLoad> {
  const all = await vpsPlans();
  const bySlug = new Map(all.map((p) => [p.slug, p]));
  const plan = (s: Size) => {
    const p = bySlug.get(s);
    if (!p) throw new Error(`nxm /ai-agents: no active VPS plan "${s}"`);
    return p;
  };
  const picks = SIZES.map((s) => [s, plan(s)] as const);
  const cheap = all.reduce((a, b) => ((a.i ?? a.p) <= (b.i ?? b.p) ? a : b));
  const from = d(cheap.i ?? cheap.p);
  const fromCap = cheap.i != null
    ? `Plans from ${from}/mo for your ${introSpan(cheap.it)}, then ${d(cheap.p)}/mo`
    : `Plans from ${from}/mo`;

  const slots: Record<string, string> = {
    "defs:html": DEFS,
    "cast:html": castHtml(),
    "plans:html": `<div class="ag-plans">${picks.map(([s, p]) => planCard(p, s, s === "standard")).join("")}</div>`,
    from_cap: fromCap,
  };
  for (const c of CAST) {
    slots[`av_${c.id}:html`] = avatarSvg(c.id);
    slots[`say_${c.id}`] = c.line;
  }
  for (const [s, p] of picks) {
    slots[`href_${s}`] = p.href;
    slots[`name_${s}`] = p.n;
    slots[`slug_${s}`] = p.slug;
    slots[`size_${s}`] = `${p.n} (${p.ram} GB)`;
    slots[`spec_${s}`] = `${p.n} · ${p.cpu} vCPU · ${p.ram} GB RAM · ${d(p.i ?? p.p)}/mo${p.i != null ? " to start" : ""}`;
  }

  return {
    slots,
    jsonLd: [productLd(
      "Nxeon VPS for AI agents",
      "An always-on NVMe VPS with full root for self-hosting AI agents such as OpenClaw, Grok-powered bots, Claude Code, MCP servers and n8n.",
      "/ai-agents",
      picks.map(([, p]) => ({ name: p.n, price: p.i ?? p.p })),
    )],
  };
}

