/* ============ AI agents: the hero's agents come online, one by one ============ */
(function hero() {
  const stage = $('#ag-stage'); if (!stage) return;
  const bots = $$('.ag-o', stage), lines = $$('.ag-lines .ln', stage), rows = $$('#ag-term-b li');
  if (RM) return;   // reduced motion: everything is shown online, nothing moves
  stage.classList.add('ag-anim');
  const on = i => [bots, lines, rows].forEach(list => list.forEach(el => { if (+el.dataset.i === i) el.classList.add('on'); }));
  let cycle = null, k = 0;
  const say = () => { bots.forEach(b => b.classList.remove('say')); bots[k % bots.length].classList.add('say'); k++; };
  const io = watch(stage, async v => {
    if (!v) { if (cycle) { clearInterval(cycle); cycle = null; bots.forEach(b => b.classList.remove('say')); } return; }
    if (!stage.dataset.booted) {
      stage.dataset.booted = '1';
      await wait(350);
      for (let i = 0; i < bots.length; i++) { on(i); await wait(520); }
    }
    if (!cycle) { say(); cycle = setInterval(say, 2800); }
  }, { threshold: 0.35 });

  /* subtle parallax: scroll drifts the layers apart, the pointer tilts them */
  const layers = [$('.ag-server', stage), ...bots].filter(Boolean);
  let px = 0, py = 0, sy = 0, raf = 0;
  const paint = () => {
    raf = 0;
    layers.forEach(el => {
      const d = +el.dataset.depth || 1;
      el.style.transform = `translate3d(${(px * d * 10).toFixed(1)}px, ${(py * d * 8 - sy * d * 0.05).toFixed(1)}px, 0)`;
    });
  };
  const ask = () => { if (!raf) raf = requestAnimationFrame(paint); };
  addEventListener('scroll', () => { const r = stage.getBoundingClientRect(); if (r.bottom < 0 || r.top > innerHeight) return; sy = clamp(innerHeight / 2 - (r.top + r.height / 2), -400, 400) * -1; ask(); }, { passive: true });
  if (matchMedia('(hover: hover)').matches) {
    stage.addEventListener('pointermove', e => { const r = stage.getBoundingClientRect(); px = (e.clientX - r.left) / r.width - 0.5; py = (e.clientY - r.top) / r.height - 0.5; ask(); });
    stage.addEventListener('pointerleave', () => { px = py = 0; ask(); });
  }
})();

/* ============ AI agents: the cast speaks on hover, focus, or a tap ============ */
(function cast() {
  const cards = $$('.ag-c');
  cards.forEach(c => c.addEventListener('click', () => {
    const was = c.classList.contains('say');
    cards.forEach(x => x.classList.remove('say'));
    if (!was) c.classList.add('say');
  }));
  document.addEventListener('keydown', e => { if (e.key === 'Escape') cards.forEach(x => x.classList.remove('say')); });
})();

/* ============ AI agents: the planned self-setup session plays once when seen ============ */
(function selfSetup() {
  const pre = $('#ag-api-b'); if (!pre || RM) return;
  const html = pre.innerHTML.split('\n');
  pre.innerHTML = html.map(l => `<span class="ln" style="opacity:0">${l || ' '}</span>`).join('');
  const spans = $$('span.ln', pre);
  const io = watch(pre, async v => {
    if (!v) return; io.disconnect();
    for (const s of spans) { s.style.transition = 'opacity .35s ease'; s.style.opacity = '1'; await wait(420); }
  }, { threshold: 0.4 });
})();

