  addEventListener('scroll', () => { const r = stage.getBoundingClientRect(); if (r.bottom < 0 || r.top > innerHeight) return; sy = clamp(innerHeight / 2 - (r.top + r.height / 2), -400, 400) * -1; ask(); }, { passive: true });
  if (matchMedia('(hover: hover)').matches) {
    stage.addEventListener('pointermove', e => { const r = stage.getBoundingClientRect(); px = (e.clientX - r.left) / r.width - 0.5; py = (e.clientY - r.top) / r.height - 0.5; ask(); });
    stage.addEventListener('pointerleave', () => { px = py = 0; ask(); });
  }
})();

/* ============ AI agents: the cast speaks on hover, focus, or a tap ============ */
(function cast() {
  const cards = $$('.ag-c');
  cards.forEach(c => c.addEventListener('click', () => {
    const was = c.classList.contains('say');
    cards.forEach(x => x.classList.remove('say'));
    if (!was) c.classList.add('say');
  }));
