import "server-only";
import fs from "node:fs";
import path from "node:path";
import type { CastId } from "./ai-agents-cast";
import { esc } from "./lib";

/**
 * /ai-agents: brand-mark slots. Each agent family can show the project's
 * OFFICIAL logo beside its (original, Nxeon-drawn) character, as a small,
 * factual "runs …" mark. That is nominative use: never a replacement for the
 * character, never styled to imply endorsement or partnership.
 *
 * Nxeon does not draw, trace or approximate these logos, and does not scrape
 * them. The owner downloads each one from the project's own press or brand kit,
 * after checking that project's brand guidelines (several restrict logo use,
 * xAI's among them), and drops it at `file` under public/. Until a file exists
 * the page shows `label` as a clean wordmark in the page's own type, and the
 * page is designed to look complete that way.
 *
 * `attribution` is printed in the page's trademark line whenever the mark is
 * shown. Keep it accurate to the owner's own guidelines.
 */
export type AgentMark = {
  /** public URL of the official file, if the owner has added one */ file: string;
  /** wordmark text used when the file is absent */ label: string;
  /** alt text for the logo image */ alt: string;
  /** required attribution, shown with the logo */ attribution: string;
};

export const MARKS: Partial<Record<CastId, AgentMark>> = {
  claw: { file: "/brand/agents/openclaw.svg", label: "OpenClaw", alt: "OpenClaw logo", attribution: "OpenClaw is a trademark of its owners." },
  visor: { file: "/brand/agents/grok.svg", label: "Grok", alt: "Grok logo", attribution: "Grok and xAI are trademarks of X.AI Corp." },
  quill: { file: "/brand/agents/claude.svg", label: "Claude Code", alt: "Claude logo", attribution: "Claude and Claude Code are trademarks of Anthropic, PBC." },
  plug: { file: "/brand/agents/mcp.svg", label: "MCP", alt: "Model Context Protocol logo", attribution: "Model Context Protocol and its logo belong to their respective owners." },
  flow: { file: "/brand/agents/n8n.svg", label: "n8n", alt: "n8n logo", attribution: "n8n is a trademark of n8n GmbH." },
};

const PUBLIC = path.join(process.cwd(), "public");

/** True when the owner has dropped the official file in place. */
export function markFileExists(m: AgentMark): boolean {
  if (!/^\/brand\/agents\/[a-z0-9-]+\.(svg|png|webp)$/.test(m.file)) return false;
  try { return fs.statSync(path.join(PUBLIC, m.file)).isFile(); } catch { return false; }
}

/** The mark for one character: the official file if present, else a wordmark. */
export function markHtml(id: CastId): string {
  const m = MARKS[id];
  if (!m) return `<span class="ag-mark is-text">Custom</span>`;
  return markFileExists(m)
    ? `<span class="ag-mark is-logo"><img src="${esc(m.file)}" alt="${esc(m.alt)}" height="18" loading="lazy" decoding="async"></span>`
    : `<span class="ag-mark is-text">${esc(m.label)}</span>`;
}

/** Attribution lines for every official mark currently shown. */
export function attributions(): string[] {
  return Object.values(MARKS).filter((m): m is AgentMark => !!m && markFileExists(m)).map((m) => m.attribution);
}

