import { CAST, CAST_DEFS, avatarSvg, type CastId } from "./ai-agents-cast";
import { attributions, markHtml } from "./ai-agents-marks";
import { esc, introSpan, productLd, usd, vpsPlans, type NxmLoad, type VpsPlan } from "./lib";

/**
 * /ai-agents: the AI agent hosting hub (native page, tools/nxm/native/ai-agents).
 *
 * System data, per request:
 *  - the three suggested sizes (starter, standard, pro): the real db.plan rows,
 *    with name, vCPU, RAM, NVMe, price and intro price as checkout has them;
 *  - every deploy link: the real deployHref() for that plan (vpsPlans);
 *  - the handshake preview's budget meter: the real Standard price against an
 *    EXAMPLE cap (labelled as an example; the feature itself is "coming soon");
 *  - official brand marks only when the owner has added the files
 *    (ai-agents-marks.ts), otherwise wordmarks;
 *  - JSON-LD Product/AggregateOffer from the same plans.
 * Missing plans throw (fail closed). The page makes no claims about agent
 * templates existing: the copy labels them "coming soon".
 *
 * The cast (ai-agents-cast.ts) is Nxeon's own original artwork. Its terminal
 * lines, chat replies and tasks are illustrative samples, labelled on the page.
 */

const SIZES = ["starter", "standard", "pro"] as const;
type Size = (typeof SIZES)[number];

/** Which cast members we suggest for each size (copy, not data). */
const FITS: Record<Size, { ids: CastId[]; good: string }> = {
  starter: { ids: ["visor", "bit", "quill", "plug"], good: "Chat bots on a hosted model, Claude Code jobs, small MCP servers" },
  standard: { ids: ["claw", "flow"], good: "OpenClaw with a few channels, n8n with Postgres" },
  pro: { ids: ["claw", "bit", "flow"], good: "Browser automation, several agents on one box" },
};

const ROCKET = `<span class="nxm-rk"><svg class="au-ic" viewBox="0 0 24 24" aria-hidden="true">${AU_ICONS.rocket}</svg></span>`;
const ARW = `<span class="nxm-arw" aria-hidden="true">→</span>`;
const d = (dollars: number) => usd(Math.round(dollars * 100));

/** The crew stage's tab list. Each tab carries its character's sample script. */
function crewTabs() {
  return CAST.map((c, i) =>
    `<button type="button" role="tab" class="crew-tab" id="crew-tab-${c.id}" aria-controls="crew-panel" aria-selected="${i === 0}" tabindex="${i === 0 ? 0 : -1}" ` +
    `style="--acc:${c.acc}" data-id="${c.id}" data-name="${esc(c.name)}" data-job="${esc(c.job)}" data-boot="${esc(c.boot.join("\n"))}" data-q="${esc(c.reply[0])}" data-a="${esc(c.reply[1])}" data-runs="${esc(c.runs)}">` +
    `<span class="crew-tab-av">${avatarSvg(c.id)}</span><span class="crew-tab-t"><b>${esc(c.name)}</b><small>runs ${esc(c.runs)}</small></span></button>`,
  ).join("");
}

/** The big avatars on the crew podium (all six; the selected one steps forward). */
function crewAvs() {
  return CAST.map((c, i) => `<span class="crew-av${i === 0 ? " on" : ""}" data-id="${c.id}" style="--acc:${c.acc}">${avatarSvg(c.id)}<span class="crew-mk" data-mark="${c.id}">${markHtml(c.id)}</span></span>`).join("");
}

function planCard(p: VpsPlan, size: Size, pop: boolean) {
  const price = p.i != null
    ? `<p class="pp"><b>${d(p.i)}</b><s>${d(p.p)}</s><span>${introSpan(p.it)}</span></p><p class="then">Then ${d(p.p)} a month</p>`
    : `<p class="pp"><b>${d(p.p)}</b><span>/month</span></p><p class="then"></p>`;
  const cta = pop
    ? `<a class="nxm-btn au-hov" href="${esc(p.href)}">${ROCKET}<span class="nxm-bt">Deploy ${esc(p.n)}</span>${ARW}</a>`
    : `<a class="nxm-glassbtn" href="${esc(p.href)}"><span class="nxm-bt">Deploy ${esc(p.n)}</span></a>`;
  const fit = FITS[size];
  return `<article class="blade${pop ? " pop" : ""}">` +
    `<div class="blade-top" aria-hidden="true"><span class="blade-led"><i></i><i></i><i></i></span><span class="blade-vent"></span></div>` +
    `<div class="blade-crew" aria-hidden="true">${fit.ids.map((id) => avatarSvg(id)).join("")}</div>` +
    (pop ? `<span class="tag">Good starting size</span>` : "") +
    `<small class="k">${esc(p.n)}</small>${price}` +
    `<dl class="blade-spec"><div><dt>vCPU</dt><dd>${p.cpu}</dd></div><div><dt>RAM</dt><dd>${p.ram} GB</dd></div><div><dt>NVMe</dt><dd>${p.disk} GB</dd></div></dl>` +
    `<p class="blade-fit">${esc(fit.good)}</p>${cta}</article>`;
}

export async function load(_p: Record<string, string>): Promise<NxmLoad> {
  const all = await vpsPlans();
  const bySlug = new Map(all.map((p) => [p.slug, p]));
  const plan = (s: Size) => {
    const p = bySlug.get(s);
    if (!p) throw new Error(`nxm /ai-agents: no active VPS plan "${s}"`);
    return p;
  };
  const picks = SIZES.map((s) => [s, plan(s)] as const);
  const cheap = all.reduce((a, b) => ((a.i ?? a.p) <= (b.i ?? b.p) ? a : b));
  const from = d(cheap.i ?? cheap.p);
  const fromCap = cheap.i != null
    ? `Plans from ${from}/mo for your ${introSpan(cheap.it)}, then ${d(cheap.p)}/mo`
    : `Plans from ${from}/mo`;

  // Handshake preview: the real Standard monthly price against an EXAMPLE cap
  // (a round figure a bit over twice the price), always labelled "example".
  const std = plan("standard");
  const stdMonthly = std.i ?? std.p;
  const capExample = Math.max(10, Math.ceil((stdMonthly * 2.2) / 5) * 5);
  const attrib = attributions();

  const slots: Record<string, string> = {
    "defs:html": CAST_DEFS,
    "crew_tabs:html": crewTabs(),
    "crew_avs:html": crewAvs(),
    "plans:html": `<div class="blades">${picks.map(([s, p]) => planCard(p, s, s === "standard")).join("")}</div>`,
    "attrib:html": attrib.length ? ` ${attrib.map(esc).join(" ")}` : "",
    from_cap: fromCap,
    budget_frac: (stdMonthly / capExample).toFixed(3),
    budget_line: `${d(stdMonthly)} of a ${d(capExample)} example monthly cap`,
  };
  const first = CAST[0];
  slots.job_claw = first.job;
  slots.boot_claw = first.boot.join("\n");
  slots.q_claw = first.reply[0];
  slots.a_claw = first.reply[1];
  for (const c of CAST) {
    slots[`av_${c.id}:html`] = avatarSvg(c.id);
    slots[`mark_${c.id}:html`] = markHtml(c.id);
    slots[`task_${c.id}`] = c.task;
  }
  for (const [s, p] of picks) {
    slots[`href_${s}`] = p.href;
    slots[`name_${s}`] = p.n;
    slots[`slug_${s}`] = p.slug;
    slots[`size_${s}`] = `${p.n} (${p.ram} GB)`;
    slots[`spec_${s}`] = `${p.n} · ${p.cpu} vCPU · ${p.ram} GB RAM · ${d(p.i ?? p.p)}/mo${p.i != null ? " to start" : ""}`;
  }

  return {
    slots,
    jsonLd: [productLd(
      "Nxeon VPS for AI agents",
      "An always-on NVMe VPS with full root for self-hosting AI agents such as OpenClaw, Grok-powered bots, Claude Code, MCP servers and n8n.",
      "/ai-agents",
      picks.map(([, p]) => ({ name: p.n, price: p.i ?? p.p })),
    )],
  };
}

