.crew-podium{position:relative;height:100%;min-height:440px;display:grid;place-items:end center}
.crew-spot{position:absolute;left:50%;top:-28px;width:120%;height:110%;translate:-50% 0;background:conic-gradient(from 165deg at 50% 0%,transparent 0deg,color-mix(in srgb,var(--acc) 30%,transparent) 15deg,transparent 30deg);filter:blur(6px);opacity:.9;pointer-events:none}
.crew-base{position:absolute;left:50%;bottom:8px;width:78%;height:56px;translate:-50% 0;border-radius:50%;background:radial-gradient(closest-side,color-mix(in srgb,var(--acc) 60%,transparent),transparent);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--acc) 50%,transparent)}
.crew-av{position:absolute;left:50%;bottom:20px;width:min(360px,92%);translate:-50% 0;opacity:0;transform:translateY(40px) scale(.82);transition:opacity .45s ease,transform .7s cubic-bezier(.2,.9,.25,1.15);z-index:2}
.crew-av.on{opacity:1;transform:none}
.crew-info{position:relative;z-index:2;min-width:0}
.crew-runs{display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin:0 0 6px}
.crew-mk{display:none}.crew-mk.on{display:inline-flex}
.crew-sample{padding:2px 9px;border-radius:999px;border:1px dashed rgba(255,255,255,.28);color:var(--muted);font:700 .62rem var(--f-mono);letter-spacing:.1em;text-transform:uppercase}
.crew-name{margin:0 0 8px;font:800 clamp(2.6rem,4.6vw,4.2rem)/.95 var(--f-display);letter-spacing:-.045em;color:#fff}
.crew-job{margin:0 0 20px;color:var(--ink-2);line-height:1.6;max-width:46ch}
.crew-term{border-radius:16px;background:rgba(4,6,15,.9);border:1px solid rgba(255,255,255,.1);overflow:hidden}
.crew-term-h{display:flex;align-items:center;gap:10px;padding:9px 12px;border-bottom:1px solid rgba(255,255,255,.07)}
.crew-term-h b{font:600 .74rem var(--f-mono);color:#C9D0E6}
.term-dots{display:inline-flex;gap:5px}.term-dots i{width:8px;height:8px;border-radius:50%;background:rgba(255,255,255,.16)}
.crew-lights{margin-left:auto;display:inline-flex;gap:6px}
.crew-lights i{width:9px;height:9px;border-radius:50%;background:#2A3150;transition:background-color .3s,box-shadow .3s}
.crew-lights i.on{background:#3FD89A;box-shadow:0 0 10px #3FD89A}
.crew-term-b{margin:0;padding:14px 16px;min-height:150px;font:12.5px/1.75 var(--f-mono);color:#B9C1D9;white-space:pre-wrap;word-break:break-word}
.crew-term-b .ok{color:#7FF0C0}.crew-term-b .cm{color:#9CC9FF}
.crew-term-b .cur{display:inline-block;width:7px;height:14px;margin-left:2px;vertical-align:-2px;background:var(--acc)}
.crew-chat{display:grid;gap:8px;margin-top:14px;min-height:96px}
.crew-chat p{margin:0;max-width:86%;padding:10px 14px;line-height:1.45;font-size:.92rem;transition:opacity .35s,transform .35s cubic-bezier(.2,.8,.2,1)}
.crew-chat .q{justify-self:end;border-radius:16px 16px 4px 16px;background:rgba(255,255,255,.08);color:#E6E9F5}
.crew-chat .a{justify-self:start;border-radius:16px 16px 16px 4px;background:color-mix(in srgb,var(--acc) 30%,#121A3A);color:#fff;border:1px solid color-mix(in srgb,var(--acc) 50%,transparent)}
.ag-crew.anim .crew-chat p{opacity:0;transform:translateY(10px)}
.ag-crew.anim .crew-chat p.in{opacity:1;transform:none}

/* ================= THE STORY (pinned + scrubbed) ================= */
.ag-story{position:relative;--c0:1;--c1:1;--c2:1;--c3:1;--c4:1;--p:1}
.ag-story.is-pinned{height:520vh}
.st-pin{position:relative;padding:clamp(70px,8vw,110px) 0}
.ag-story.is-pinned .st-pin{position:sticky;top:0;height:100vh;height:100svh;padding:0;display:flex;align-items:center}
.st-in{display:grid;grid-template-columns:minmax(0,.85fr) minmax(0,1.15fr);gap:clamp(30px,5vw,70px);align-items:center;width:100%}
.st-ch{list-style:none;margin:0;padding:0;display:grid;gap:18px;counter-reset:ch}
.st-ch li{display:grid;gap:6px;padding-left:20px;border-left:2px solid rgba(255,255,255,.1);transition:opacity .4s,border-color .4s}
