.ag-story.is-pinned .st-ch li{opacity:.28}
.ag-story.is-pinned .st-ch li.on{opacity:1;border-color:var(--acc)}
.st-prog{height:3px;margin-top:26px;border-radius:3px;background:rgba(255,255,255,.08);overflow:hidden}
.st-prog i{display:block;height:100%;background:linear-gradient(90deg,#3B6BE8,#7B3FEF,#E5197E);transform-origin:0 50%;transform:scaleX(var(--p))}
.st-vis{position:relative;aspect-ratio:1/0.86;border-radius:32px;overflow:hidden;background:linear-gradient(180deg,#121A44,#0A0F27);border:1px solid rgba(160,170,255,.16)}
.st-sky,.st-night,.st-stars{position:absolute;inset:0}
.st-night{background:linear-gradient(180deg,#03050F,#070B1E);opacity:var(--c3)}
.st-stars{background-image:radial-gradient(1.2px 1.2px at 15% 20%,#fff 50%,transparent 51%),radial-gradient(1px 1px at 40% 12%,#fff 50%,transparent 51%),radial-gradient(1.2px 1.2px at 70% 22%,#fff 50%,transparent 51%),radial-gradient(1px 1px at 85% 35%,#fff 50%,transparent 51%);background-size:300px 220px;opacity:calc(var(--c3) * .7)}
.st-moon{position:absolute;right:10%;top:9%;width:54px;height:54px;border-radius:50%;background:radial-gradient(circle at 35% 35%,#FFF6D8,#E7D7A4 60%,#B8A46A);box-shadow:0 0 50px 14px rgba(255,240,200,.16);opacity:var(--c3);transform:translateY(calc((1 - var(--c3)) * 80px))}
.st-idea{position:absolute;left:8%;top:12%;opacity:calc(1 - var(--c1));transform:translateY(calc(var(--c1) * -40px))}
.st-bubble{display:block;padding:14px 18px;border-radius:20px 20px 20px 6px;background:#F3F5FF;color:#141B38;font:800 clamp(1rem,1.6vw,1.3rem)/1.25 var(--f-display);max-width:300px;box-shadow:0 24px 50px -20px rgba(0,0,0,.7)}
.st-server{position:absolute;left:50%;top:46%;width:34%;translate:-50% -50%;opacity:var(--c1);transform:scale(calc(.6 + .4 * var(--c1)))}
.st-server img{display:block;width:100%;height:auto;filter:drop-shadow(0 30px 50px rgba(0,0,0,.6)) drop-shadow(0 0 50px rgba(123,63,239,.5))}
.st-on{position:absolute;left:50%;top:100%;translate:-50% 8px;padding:4px 12px;border-radius:999px;background:rgba(8,12,28,.85);border:1px solid rgba(63,216,154,.4);color:#7FF0C0;font:700 .68rem var(--f-mono);letter-spacing:.08em;text-transform:uppercase;white-space:nowrap}
.st-crew .sc{position:absolute;width:19%;opacity:var(--c2)}
.st-crew .s1{left:13%;top:58%;transform:translate(calc((1 - var(--c2)) * -220px),0) rotate(calc((1 - var(--c2)) * -20deg))}
.st-crew .s2{left:67%;top:56%;transform:translate(calc((1 - var(--c2)) * 260px),0) rotate(calc((1 - var(--c2)) * 20deg))}
.st-crew .s3{left:41%;top:4%;width:16%;transform:translateY(calc((1 - var(--c2)) * -200px))}
.st-laptop{position:absolute;left:6%;bottom:7%;display:flex;align-items:center;gap:8px;padding:8px 12px;border-radius:12px;background:rgba(8,12,28,.85);border:1px solid rgba(255,255,255,.12);opacity:var(--c3);transform:translateY(calc((1 - var(--c3)) * 30px))}
.st-laptop i{width:22px;height:14px;border-radius:3px;border:2px solid #5E6788;border-bottom-width:4px}
.st-laptop b{font:600 .75rem var(--f-body);color:#C7CEE6}
.st-laptop em{font:700 .62rem var(--f-mono);color:var(--muted);text-transform:uppercase;letter-spacing:.1em}
.st-log{list-style:none;position:absolute;right:6%;bottom:7%;margin:0;padding:10px 12px;border-radius:12px;background:rgba(8,12,28,.85);border:1px solid rgba(255,255,255,.12);display:grid;gap:3px;font:500 .72rem var(--f-mono);color:#B9C1D9;opacity:var(--c3);transform:translateY(calc((1 - var(--c3)) * 30px))}
.st-log li::before{content:"✓ ";color:#3FD89A}
.st-shell{position:absolute;left:50%;top:50%;width:76%;aspect-ratio:1/0.82;translate:-50% -50%;opacity:var(--c4);transform:scale(calc(1.3 - .3 * var(--c4)))}
.st-shell i{position:absolute;inset:0;border-radius:44% 44% 40% 40%;border:2px solid rgba(62,220,242,.65);box-shadow:0 0 40px rgba(62,220,242,.35),inset 0 0 60px rgba(123,63,239,.35);background:radial-gradient(closest-side,transparent 70%,rgba(62,220,242,.08))}
.st-shell span{position:absolute;left:50%;top:-12px;translate:-50% 0;padding:3px 10px;border-radius:999px;background:#0A1024;border:1px solid rgba(62,220,242,.5);color:#BFF4FF;font:700 .64rem var(--f-mono);letter-spacing:.06em;white-space:nowrap}
.st-ping{position:absolute;width:10px;height:10px;border-radius:50%;background:#FF5B7F;box-shadow:0 0 12px #FF5B7F;opacity:0}
.st-ping.p1{left:2%;top:40%;--tx:60px;--ty:10px}.st-ping.p2{right:2%;top:30%;--tx:-60px;--ty:20px}.st-ping.p3{left:46%;bottom:0;--tx:0;--ty:-50px}
.st-label{position:absolute;left:14px;top:12px;margin:0;padding:2px 8px;border-radius:999px;border:1px dashed rgba(255,255,255,.28);color:var(--muted);font:700 .6rem var(--f-mono);letter-spacing:.1em;text-transform:uppercase}
@media (prefers-reduced-motion:no-preference){
  .ag-story[data-c="4"] .st-ping{animation:st-ping 3s ease-in infinite}
