/* ============ AI agents v2: shared state, pause, off-screen pausing ============ */
const AG = (() => {
  const root = $('.ag-root'); if (!root) return null;
  root.classList.add('ag-js');
  const st = { paused: false, listeners: [] };
  const btn = $('#ag-pause');
  const svgs = () => $$('svg.wk-net', root);
  const apply = () => {
    root.classList.toggle('ag-paused', st.paused);
    if (btn) { btn.setAttribute('aria-pressed', String(st.paused)); $('.tx', btn).textContent = st.paused ? 'Play animations' : 'Pause animations'; }
    $$('.wk-pause', root).forEach(b => { b.setAttribute('aria-pressed', String(st.paused)); b.textContent = st.paused ? 'Play' : 'Pause'; });
    svgs().forEach(s => { try { st.paused ? s.pauseAnimations() : s.unpauseAnimations(); } catch (e) {} });
