/* ============ THE NIGHT SHIFT: six agents working in parallel (illustrative) ============ */
(function nightShift() {
  const box = $('#ag-work'); if (!box || !AG) return;
  const agents = $$('.wk-a', box), beats = $$('.wk-beats li', box), fly = $('#wk-fly'), q = $('.wk-q', box);
  const tick = $('#wk-ticker'), count = $('#wk-count'), clock = $('#wk-clock');
  const accs = agents.map(a => getComputedStyle(a).getPropertyValue('--acc').trim() || '#7B3FEF');
  const names = agents.map(a => $('b', a).textContent), tasks = agents.map(a => $('.wk-task', a).textContent);
  const verbs = ['replied to a chat', 'summarised 12 pages', 'deployed the site', 'answered a webhook', 'ran the nightly job', 'triaged the inbox'];
  let minutes = 18 * 60, done = 0, running = false, visible = false, timer = 0;
  const fmt = m => { m = ((m % 1440) + 1440) % 1440; return String((m / 60) | 0).padStart(2, '0') + ':' + String(m % 60).padStart(2, '0'); };
  const setClock = () => {
    clock.textContent = fmt(minutes);
    const hh = (minutes % 1440) / 60, night = hh >= 20 || hh < 5 ? 1 : hh >= 18 ? (hh - 18) / 2 : hh < 6 ? 1 - (hh - 5) : 0;
    box.style.setProperty('--night', night.toFixed(2));
  };
  const beat = b => beats.forEach((li, i) => li.classList.toggle('on', i === b));
  const sleep = ms => new Promise(r => { timer = setTimeout(r, ms); });
  const waitPlay = async () => { while (AG.paused || !visible) await sleep(250); };
  const rel = el => { const a = box.getBoundingClientRect(), r = el.getBoundingClientRect(); return [r.left - a.left + r.width / 2, r.top - a.top + r.height / 2]; };
  const log = (txt) => {
    const li = document.createElement('li'); li.className = 'new';
    li.innerHTML = `<time>${fmt(minutes)}</time>${txt}<em>✓</em>`;
    tick.prepend(li); while (tick.children.length > 4) tick.lastElementChild.remove();
  };
  const burst = (x, y, c) => {
    for (let i = 0; i < 10; i++) {
      const d = document.createElement('i'); d.className = 'wk-burst'; d.style.setProperty('--acc', c); fly.appendChild(d);
      const a = (i / 10) * 6.283, r = 34 + Math.random() * 26;
      d.animate([{ transform: `translate(${x}px,${y}px) scale(1)`, opacity: 1 }, { transform: `translate(${x + Math.cos(a) * r}px,${y + Math.sin(a) * r}px) scale(.2)`, opacity: 0 }], { duration: 700, easing: 'cubic-bezier(.2,.8,.2,1)' }).onfinish = () => d.remove();
    }
  };
  const flyCard = (i) => new Promise(res => {
    const c = document.createElement('span'); c.className = 'wk-fc'; c.style.setProperty('--acc', accs[i]); c.textContent = tasks[i]; fly.appendChild(c);
    const [x0, y0] = rel(q), [x1, y1] = rel($('.wk-card', agents[i]));
    const cw = c.offsetWidth / 2, ch = c.offsetHeight / 2;
    const anim = c.animate([
      { transform: `translate(${x0 - cw}px,${y0 - ch}px) scale(.6)`, opacity: 0 },
      { transform: `translate(${x0 - cw}px,${y0 - ch - 20}px) scale(1)`, opacity: 1, offset: .2 },
      { transform: `translate(${(x0 + x1) / 2 - cw}px,${Math.min(y0, y1) - ch - 50}px) scale(1.05)`, opacity: 1, offset: .6 },
      { transform: `translate(${x1 - cw}px,${y1 - ch}px) scale(.7)`, opacity: 0 }], { duration: 900, easing: 'cubic-bezier(.45,0,.2,1)' });
    anim.onfinish = () => { c.remove(); res(); };
  });
  const work = (i) => new Promise(res => {
    const a = agents[i], bar = $('.wk-bar i', a), av = $('.av', a);
    a.classList.add('is-working'); av.classList.add('is-working');
    const dur = 1800 + ((i * 577) % 1700);
    const anim = bar.animate([{ transform: 'scaleX(0)' }, { transform: 'scaleX(1)' }], { duration: dur, easing: 'cubic-bezier(.4,.1,.3,1)', fill: 'forwards' });
    if (AG.paused) anim.pause();
    anim.onfinish = () => {
      a.classList.remove('is-working'); av.classList.remove('is-working'); a.classList.add('is-done'); av.classList.add('is-happy');
      const [x, y] = rel($('.wk-av', a)); burst(x, y, accs[i]);
      minutes += 7 + (i * 3); setClock(); done++; count.textContent = String(done);
      log(`${names[i]} ${verbs[i]}`);
      res();
    };
  });
  const reset = () => agents.forEach(a => { a.classList.remove('is-done', 'is-working'); const av = $('.av', a); av.classList.remove('is-happy', 'is-working'); $('.wk-bar i', a).getAnimations().forEach(x => x.cancel()); });
  const loop = async () => {
    if (running) return; running = true;
    for (;;) {
      await waitPlay();
      // beat 1: the queue fills
      beat(0); box.classList.remove('hot'); q.innerHTML = '';
      for (let i = 0; i < agents.length; i++) { const t = document.createElement('i'); t.style.setProperty('--c', accs[i]); q.appendChild(t); await sleep(140); t.classList.add('in'); }
      await sleep(500); await waitPlay();
      // beat 2: dispatch, one card to each agent
      beat(1); box.classList.add('hot');
      const jobs = [];
      for (let i = 0; i < agents.length; i++) {
        await waitPlay(); const t = q.children[0]; t && t.remove();
        jobs.push(flyCard(i).then(() => { beat(2); return work(i); }));
        await sleep(220);
