    names.forEach((n, i) => { const li = document.createElement('li'); li.innerHTML = `<time>${fmt(minutes - (5 - i) * 31)}</time>${n} ${verbs[i]}<em>✓</em>`; if (i > 1) tick.prepend(li); });
    while (tick.children.length > 4) tick.lastElementChild.remove();
    count.textContent = '6'; return;
  }
  setClock();
  watch(box, v => { visible = v; if (v) loop(); }, { threshold: 0.25 });
