/* ============ MEET THE CREW: pick a character, it steps forward and boots (illustrative) ============ */
(function crew() {
  const wrap = $('#ag-crew'); if (!wrap || !AG) return;
  const tabs = $$('.crew-tab', wrap), avs = $$('.crew-av', wrap), marks = $$('.crew-mk', wrap);
  const name = $('#crew-name'), job = $('#crew-job'), term = $('#crew-term'), qq = $('#crew-q'), aa = $('#crew-a'), sr = $('#crew-sr');
  const lights = $$('.crew-lights i', wrap), panel = $('#crew-panel');
  let run = 0;
  const esc = s => s.replace(/[&<>]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c]));
  const line = l => `<span class="${l.startsWith('✓') ? 'ok' : ''}">${esc(l)}</span>`;
  const select = async (tab, focus) => {
    const id = tab.dataset.id, my = ++run;
    tabs.forEach(t => { const on = t === tab; t.setAttribute('aria-selected', String(on)); t.tabIndex = on ? 0 : -1; });
    if (focus) tab.focus();
    panel.setAttribute('aria-labelledby', tab.id);
    AG.root.style.setProperty('--acc', tab.dataset.acc);
    avs.forEach(a => { a.classList.toggle('on', a.dataset.id === id); $('.av', a).classList.remove('is-happy'); });
    marks.forEach(m => m.classList.toggle('on', m.dataset.id === id));
    name.textContent = tab.dataset.name; job.textContent = tab.dataset.job;
    const boot = tab.dataset.boot.split('\n');
    sr.textContent = `${tab.dataset.name}. ${tab.dataset.job} Sample setup: ${boot.join('. ')}. Sample reply: ${tab.dataset.a}`;
    qq.textContent = tab.dataset.q; aa.textContent = tab.dataset.a;
    if (RM) { term.innerHTML = boot.map(line).join('\n'); return; }
    wrap.classList.add('anim'); [qq, aa].forEach(p => p.classList.remove('in')); lights.forEach(l => l.classList.remove('on'));
    term.innerHTML = '';
    const cur = '<span class="cur"></span>';
    let out = [];
    for (let li = 0; li < boot.length; li++) {
      const l = boot[li];
      if (l.startsWith('$')) {
        for (let k = 1; k <= l.length; k += 2) { if (my !== run) return; while (AG.paused) await wait(200); term.innerHTML = [...out, esc(l.slice(0, k)) + cur].join('\n'); await wait(18); }
      } else { await wait(260); }
      if (my !== run) return;
      out.push(line(l)); term.innerHTML = out.join('\n') + cur;
      if (li === 1) lights[0].classList.add('on'); if (li === 3) lights[1].classList.add('on');
    }
    lights[2].classList.add('on');
