  watch($('#crew'), v => { if (!v) AG.root.style.setProperty('--acc', '#7B3FEF'); else { const t = tabs.find(x => x.getAttribute('aria-selected') === 'true'); t && AG.root.style.setProperty('--acc', t.dataset.acc); } });
})();

