cat > test/ai-agents-page.test.ts <<'EOF'
import test from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import path from "node:path";
import { CAST, CAST_DEFS, avatarSvg } from "../app/nxm/_data/ai-agents-cast";
import { MARKS, attributions, markFileExists, markHtml } from "../app/nxm/_data/ai-agents-marks";
import { BODY_HTML } from "../app/nxm/_pages/ai-agents/content";
import { PAGE_SCRIPT } from "../app/nxm/_pages/ai-agents/script";
import { SEO } from "../app/nxm/_seo/registry";
import { fitTitle } from "../lib/seo-text";

const ROOT = path.join(__dirname, "..");
const LOADER = fs.readFileSync(path.join(ROOT, "app/nxm/_data/ai-agents.ts"), "utf8");
const text = BODY_HTML.replace(/<[^>]+>/g, " ");

test("ai-agents: every slot the page uses is one the loader fills", () => {
  const used = new Set([...BODY_HTML.matchAll(/\{\{nxm:([a-zA-Z0-9_.:-]+)\}\}/g)].map((m) => m[1]));
  const filled = new Set<string>(["defs:html", "crew_tabs:html", "crew_avs:html", "crew_marks:html", "plans:html", "attrib:html", "from_cap", "budget_frac", "budget_line", "job_first", "boot_first", "q_first", "a_first"]);
  for (const c of CAST) for (const k of [`av_${c.id}:html`, `mark_${c.id}:html`, `task_${c.id}`]) filled.add(k);
  for (const s of ["starter", "standard", "pro"]) for (const k of ["href", "name", "slug", "size", "spec"]) filled.add(`${k}_${s}`);
  for (const k of used) assert.ok(filled.has(k), `slot {{nxm:${k}}} has no value in the loader`);
  for (const k of ["defs:html", "crew_tabs:html", "crew_avs:html", "crew_marks:html", "plans:html", "attrib:html", "budget_frac", "budget_line", "av_${c.id}:html", "mark_${c.id}:html", "task_${c.id}", "href_${s}", "spec_${s}"]) assert.ok(LOADER.includes(k), k);
});

test("ai-agents: no hardcoded prices in the page markup (they come from db.plan)", () => {
  assert.doesNotMatch(BODY_HTML, /\$\d/);
});

test("ai-agents: planned features are labelled, samples are labelled, nothing is claimed", () => {
  for (const planned of ["One-click template: coming soon", "Starter template: coming soon", "MCP host template: coming soon", "Agent template: coming soon"]) assert.ok(text.includes(planned), planned);
  assert.match(text, /Planned API, shown as a preview\. It isn't available yet\./);
  assert.match(text, /Illustrative sample\. The tasks, times and counter are made up/);
  assert.match(text, /not live data or a measure of real throughput/);
  assert.match(BODY_HTML, /crew-sample">Illustrative sample</);
  assert.match(text, /not the logos or mascots/);
  assert.match(text, /not affiliated with or endorsed by them/);
  assert.match(text, /47 seconds away\./);
  assert.doesNotMatch(BODY_HTML, /logos\/(claude|openai|discord)\.svg/);
  assert.doesNotMatch(text, /\bprovider\b/i);
});

test("ai-agents: avatars are original inline SVG with the shared anatomy", () => {
  assert.equal(new Set(CAST.map((c) => c.id)).size, CAST.length);
  assert.match(CAST_DEFS, /^<svg id="ag-defs"/);
  for (const c of CAST) {
    const plain = avatarSvg(c.id);
    assert.match(plain, /^<svg class="av av-[a-z]+" viewBox="0 0 160 160" aria-hidden="true"/);
    assert.doesNotMatch(plain, /<image|href="http|<use/);
    for (const part of ["av-body", "av-eyes", "av-pupils", "av-mouth", "m-happy", "sig-"]) assert.ok(plain.includes(part), `${c.name} has ${part}`);
    assert.match(avatarSvg(c.id, `${c.name} "x"`), /role="img" aria-label="[^"]*&quot;x&quot;"/);
    assert.ok(c.line.length <= 60 && c.boot.length >= 3 && c.reply.length === 2 && c.task, `${c.name}'s copy is complete`);
  }
});

test("ai-agents: brand marks fall back to wordmarks, and only accept files under /brand/agents", () => {
  for (const m of Object.values(MARKS)) {
    assert.match(m!.file, /^\/brand\/agents\/[a-z0-9-]+\.svg$/);
    assert.ok(m!.attribution && m!.alt && m!.label);
  }
  // the repo ships no third-party logo files: every mark renders as text
  for (const c of CAST) assert.match(markHtml(c.id), /class="ag-mark is-text"/);
  assert.deepEqual(attributions(), []);
  assert.equal(markFileExists({ file: "/../../etc/passwd", label: "x", alt: "x", attribution: "x" }), false);
  assert.equal(markFileExists({ file: "https://example.com/x.svg", label: "x", alt: "x", attribution: "x" }), false);
});

test("ai-agents: motion is controllable and honours reduced motion", () => {
  assert.match(BODY_HTML, /id="ag-pause" aria-pressed="false"/);
  assert.match(PAGE_SCRIPT, /pauseAnimations/);
  assert.match(PAGE_SCRIPT, /is-off/);
  assert.match(PAGE_SCRIPT, /if \(RM\)/);
  const css = fs.readFileSync(path.join(ROOT, "tools/nxm/native/ai-agents/page.css"), "utf8");
  assert.match(css, /@media \(prefers-reduced-motion:reduce\)/);
  // every keyframe animates transform/opacity only (GPU-friendly)
  for (const m of css.matchAll(/@keyframes [\w-]+\{([\s\S]*?\})\}/g)) {
    for (const prop of m[1].matchAll(/([a-z-]+):/g)) assert.ok(["transform", "opacity"].includes(prop[1]), `keyframe uses ${prop[1]}`);
  }
});

test("ai-agents: route is registered for SEO and the live-route switch", () => {
  const e = SEO["/ai-agents"];
  assert.ok(e && e.title && e.description && e.crumb);
  assert.equal(fitTitle(e.title, " — Nxeon"), e.title, "title fits the budget without being cut");
  const live = JSON.parse(fs.readFileSync(path.join(ROOT, "app/nxm/_data/live-routes.json"), "utf8"));
  assert.ok(JSON.stringify(live).includes('"/ai-agents"'));
});
EOF
