.st-back i:nth-child(odd){--h:78%}.st-back i:nth-child(3n){--h:92%}
.st-floor{position:absolute;left:-30%;right:-30%;bottom:-14%;height:44%;perspective:500px;-webkit-mask-image:linear-gradient(180deg,transparent,#000 50%);mask-image:linear-gradient(180deg,transparent,#000 50%)}
.st-floor i{position:absolute;inset:0;transform:rotateX(66deg) translateY(calc(var(--p) * 64px));transform-origin:50% 0;background-image:linear-gradient(rgba(123,63,239,.35) 1px,transparent 1px),linear-gradient(90deg,rgba(62,220,242,.22) 1px,transparent 1px);background-size:44px 44px}
.st-wires{position:absolute;inset:0;width:100%;height:100%;overflow:visible}
