.st-crew .s1{left:13%;top:58%;opacity:1;transform:translate(calc((1 - var(--c2)) * -10px),calc((1 - var(--c2)) * 30px)) scale(calc(.9 + .1 * var(--c2)))}
.st-idea{left:20%;top:30%}
.st-zz{position:absolute;right:12%;bottom:21%;font:800 1rem var(--f-display);letter-spacing:.3em;color:#C7CEE6;opacity:calc(var(--c3) * (1 - var(--c4)) * .9)}
.st-server{transform:scale(calc(.6 + .4 * var(--c1))) translateY(calc((1 - var(--c1)) * 30px))}
.ag-story[data-c="3"] .st-server img{filter:drop-shadow(0 30px 50px rgba(0,0,0,.6)) drop-shadow(0 0 70px rgba(62,220,242,.6))}

/* ---------- responsive v3 ---------- */
