103	/* ============ THE NIGHT SHIFT: six agents working in parallel (illustrative) ============ */
104	(function nightShift() {
105	  const box = $('#ag-work'); if (!box || !AG) return;
106	  const agents = $$('.wk-a', box), beats = $$('.wk-beats li', box), fly = $('#wk-fly'), q = $('.wk-q', box);
107	  const tick = $('#wk-ticker'), count = $('#wk-count'), clock = $('#wk-clock');
108	  const accs = agents.map(a => getComputedStyle(a).getPropertyValue('--acc').trim() || '#7B3FEF');
109	  const names = agents.map(a => $('b', a).textContent), tasks = agents.map(a => $('.wk-task', a).textContent);
110	  const verbs = ['replied to a chat', 'summarised 12 pages', 'deployed the site', 'answered a webhook', 'ran the nightly job', 'triaged the inbox'];
111	  let minutes = 18 * 60, done = 0, running = false, visible = false, timer = 0;
112	  const fmt = m => { m = ((m % 1440) + 1440) % 1440; return String((m / 60) | 0).padStart(2, '0') + ':' + String(m % 60).padStart(2, '0'); };
113	  const setClock = () => {
114	    clock.textContent = fmt(minutes);
115	    const hh = (minutes % 1440) / 60, night = hh >= 20 || hh < 5 ? 1 : hh >= 18 ? (hh - 18) / 2 : hh < 6 ? 1 - (hh - 5) : 0;
116	    box.style.setProperty('--night', night.toFixed(2));
117	  };
118	  const beat = b => beats.forEach((li, i) => li.classList.toggle('on', i === b));
119	  const sleep = ms => new Promise(r => { timer = setTimeout(r, ms); });
120	  const waitPlay = async () => { while (AG.paused || !visible) await sleep(250); };
121	  const rel = el => { const a = box.getBoundingClientRect(), r = el.getBoundingClientRect(); if (!r.width) return [a.width / 2, 30]; return [r.left - a.left + r.width / 2, r.top - a.top + r.height / 2]; };
122	  const log = (txt) => {
123	    const li = document.createElement('li'); li.className = 'new';
124	    li.innerHTML = `<time>${fmt(minutes)}</time>${txt}<em>✓</em>`;
125	    tick.prepend(li); while (tick.children.length > 4) tick.lastElementChild.remove();
126	  };
127	  const burst = (x, y, c) => {
128	    for (let i = 0; i < 10; i++) {
129	      const d = document.createElement('i'); d.className = 'wk-burst'; d.style.setProperty('--acc', c); fly.appendChild(d);
130	      const a = (i / 10) * 6.283, r = 34 + Math.random() * 26;
131	      d.animate([{ transform: `translate(${x}px,${y}px) scale(1)`, opacity: 1 }, { transform: `translate(${x + Math.cos(a) * r}px,${y + Math.sin(a) * r}px) scale(.2)`, opacity: 0 }], { duration: 700, easing: 'cubic-bezier(.2,.8,.2,1)' }).onfinish = () => d.remove();
132	    }
133	  };
134	  const flyCard = (i) => new Promise(res => {
135	    const c = document.createElement('span'); c.className = 'wk-fc'; c.style.setProperty('--acc', accs[i]); c.textContent = tasks[i]; fly.appendChild(c);
136	    const [x0, y0] = rel(q), [x1, y1] = rel($('.wk-card', agents[i]));
137	    const cw = c.offsetWidth / 2, ch = c.offsetHeight / 2;
138	    const anim = c.animate([
139	      { transform: `translate(${x0 - cw}px,${y0 - ch}px) scale(.6)`, opacity: 0 },
140	      { transform: `translate(${x0 - cw}px,${y0 - ch - 20}px) scale(1)`, opacity: 1, offset: .2 },
141	      { transform: `translate(${(x0 + x1) / 2 - cw}px,${Math.min(y0, y1) - ch - 50}px) scale(1.05)`, opacity: 1, offset: .6 },
142	      { transform: `translate(${x1 - cw}px,${y1 - ch}px) scale(.7)`, opacity: 0 }], { duration: 900, easing: 'cubic-bezier(.45,0,.2,1)' });
143	    anim.onfinish = () => { c.remove(); res(); };
144	  });
145	  const work = (i) => new Promise(res => {
146	    const a = agents[i], bar = $('.wk-bar i', a), av = $('.av', a);
147	    a.classList.add('is-working'); av.classList.add('is-working');
148	    const dur = 1800 + ((i * 577) % 1700);
149	    const anim = bar.animate([{ transform: 'scaleX(0)' }, { transform: 'scaleX(1)' }], { duration: dur, easing: 'cubic-bezier(.4,.1,.3,1)', fill: 'forwards' });
150	    if (AG.paused) anim.pause();
151	    anim.onfinish = () => {
152	      a.classList.remove('is-working'); av.classList.remove('is-working'); a.classList.add('is-done'); av.classList.add('is-happy');
153	      const [x, y] = rel($('.wk-av', a)); burst(x, y, accs[i]);
154	      minutes += 7 + (i * 3); setClock(); done++; count.textContent = String(done);
