156	      res();
157	    };
158	  });
159	  const reset = () => agents.forEach(a => { a.classList.remove('is-done', 'is-working'); const av = $('.av', a); av.classList.remove('is-happy', 'is-working'); $('.wk-bar i', a).getAnimations().forEach(x => x.cancel()); });
160	  const loop = async () => {
161	    if (running) return; running = true;
162	    for (;;) {
163	      await waitPlay();
