186	    minutes = 2 * 60 + 14; box.style.setProperty('--night', '1'); clock.textContent = fmt(minutes); beat(3);
187	    names.forEach((n, i) => { const li = document.createElement('li'); li.innerHTML = `<time>${fmt(minutes - (5 - i) * 31)}</time>${n} ${verbs[i]}<em>✓</em>`; if (i > 1) tick.prepend(li); });
188	    while (tick.children.length > 4) tick.lastElementChild.remove();
189	    count.textContent = '6'; return;
190	  }
191	  /* the glowing lines run from the server to wherever the layout put each agent */
192	  const stage = $('.wk-stage', box), svg = $('.wk-net', box);
193	  const route = () => {
194	    if (!svg || !stage) return; const S = stage.getBoundingClientRect(); if (!S.width) return;
195	    const cx = 500, cy = 280;
196	    agents.forEach((a, i) => {
197	      const r = $('.wk-av', a).getBoundingClientRect(), path = $('#wk-p' + i, svg); if (!path || !r.width) return;
198	      const x = ((r.left + r.width / 2 - S.left) / S.width) * 1000, y = ((r.top + r.height / 2 - S.top) / S.height) * 560;
199	      path.setAttribute('d', `M${cx} ${cy} C${(cx + (x - cx) * 0.25).toFixed(0)} ${(cy + (y - cy) * 0.9).toFixed(0)} ${(x - (x - cx) * 0.4).toFixed(0)} ${y.toFixed(0)} ${x.toFixed(0)} ${y.toFixed(0)}`);
200	    });
201	  };
202	  route(); addEventListener('resize', route, { passive: true });
203	  setClock();
204	  watch(box, v => { visible = v; if (v) { route(); loop(); } }, { threshold: 0.25 });

